// The practice deck, in teaching order: the curated beginner deck first, then the
// most frequent remaining characters. The data is generated by scripts/build_deck.py.
import { DECK_DATA } from './deck-data.js';

/** @type {{hanzi: string, pinyin: string, readings: string[], meaning: string}[]} */
export const CHARACTERS = DECK_DATA.split('\n').map((line) => {
  const [hanzi, pinyin, others, meaning] = line.split('|');
  return { hanzi, pinyin, readings: [pinyin, ...(others ? others.split(' ') : [])], meaning };
});
